const D = { energy:.6, scale:1, density:.5, speed:1, turn:.5, hue:32, x:.5, y:.5, style:'concrete', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };

// `scale` drives the RECURSION RATIO — big scale = chunky landings, few floors
const rr = cl(.87 - .165*cl(P.scale,.35,2.4), .50, .87);
const asp = .74, B0 = u*.90;
const NL = Math.min(26, Math.ceil(Math.log(B0/1.4)/Math.log(1/rr)) + 1);
const LMIN = -(Math.ceil(Math.log(2.5*u/B0)/Math.log(1/rr)) + 1);
const turn = cl(P.turn,0,2) * Math.PI/2;

// ---- real-time descent; floor content keyed on ABSOLUTE index -> no re-phase
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.d = (S.d||0) + dt * P.speed * (.10 + .12*K.intensity) * (.6 + .5*P.energy);
const ph = S.d - Math.floor(S.d), lbase = Math.floor(S.d);

// ---- incommensurate precession: the shaft never re-aligns -------------------
const th0 = K.t*.0305 + .22*Math.sin(K.t*.173) + .10*Math.sin(K.t*.412+1.1);
const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const glow = (.40 + .60*P.energy)*(.55 + .5*K.intensity) + bass*.3;
const lz = 3.0 + 3.2*Math.sin(K.t*.091) + 1.4*Math.sin(K.t*.233+2.0) + .8*Math.sin(K.t*.571);

const cx = cl(P.x,.15,.85)*width  + u*.014*Math.sin(K.t*.37)*P.energy;
const cy = cl(P.y,.15,.85)*height + u*.014*Math.sin(K.t*.61+1.4)*P.energy;
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const bp = (sty==='blueprint'), paper = (sty==='engraving'), noir = (sty==='noir');

const rot = (px,py,a) => [cx + px*Math.cos(a) - py*Math.sin(a), cy + px*Math.sin(a) + py*Math.cos(a)];
function per(hx,hy,a,t){
  const q = (((t%1)+1)%1)*4, si = Math.floor(q)%4, fq = q - Math.floor(q);
  let px, py;
  if (si===0){ px=-hx+2*hx*fq; py=-hy; }
  else if (si===1){ px=hx; py=-hy+2*hy*fq; }
  else if (si===2){ px=hx-2*hx*fq; py=hy; }
  else { px=-hx; py=hy-2*hy*fq; }
  return rot(px,py,a);
}

// ---- cached ground + shaft-bottom glow --------------------------------------
const gk = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+Math.round(cx/6)+'|'+Math.round(cy/6);
if (!S.bgb || S.gk !== gk){
  const g = (S.bgb && S.bgb.width===width && S.bgb.height===height) ? S.bgb : createGraphics(width,height);
  g.colorMode(HSB,360,100,100,100); g.noStroke();
  let gc = [H, 10, 9];
  if (bp) gc = [212, 62, 19]; else if (paper) gc = [40, 9, 85];
  else if (noir) gc = [H, 24, 6]; else if (sty==='terrazzo') gc = [38, 12, 22];
  g.fill(gc[0],gc[1],gc[2],100); g.rect(0,0,width,height);
  if (!bp && !paper){
    g.blendMode(ADD);
    for (let i=20;i>=1;i--){ const q=i/20;
      g.fill(H, 36, 100, 1.4 + 2.4*(1-q));
      g.ellipse(cx, cy, u*.40*q, u*.40*q*asp);
    }
    g.blendMode(BLEND);
  }
  S.bgb = g; S.gk = gk;
}
image(S.bgb, 0, 0);

// ---- tones ------------------------------------------------------------------
function landing(ai, near, lit){
  const tv = fr(ai*3.11);
  const v = (.16 + .70*lit + .12*tv) * (.42 + .58*near);
  if (bp)  return [212, 60, cl(12 + 16*v, 8, 34)];
  if (paper) return [40, 8, cl(92 - 42*(1-v), 38, 95)];
  if (noir)  return [H, cl(30 - 18*lit, 4, 40), cl(2 + 44*v*v*1.4, 1, 62)];
  if (sty==='terrazzo') return [38, cl(16 + 10*tv, 4, 34), cl(24 + 62*v, 12, 92)];
  return [H, cl(5 + 9*tv, 2, 18), cl(6 + 76*v, 3, 88)];
}
function ink(a){
  if (bp) stroke(190, 30, 100, a);
  else if (paper) stroke(30, 24, 14, a);
  else if (noir) stroke(H, 20, 96, a);
  else if (sty==='terrazzo') stroke(44, 24, 92, a);
  else stroke(H, 8, 92, a);
}

// ---- floors, deep -> near ---------------------------------------------------
const SW = Math.max(1, u*.0016);
strokeWeight(SW);
const ntd = Math.round(9 + P.density*15);
for (let L = NL; L >= LMIN; L--){
  const e = L - ph;
  const s = B0 * Math.pow(rr, e);
  if (s < 1.2 || s > u*11) continue;
  const ai = lbase + L;
  const near = cl(1 - (e - LMIN)/(NL - LMIN), 0, 1);
  const pd = e - lz;
  const lit = cl(.14 + .86*Math.exp(-pd*pd*.16), 0, 1) * (.45 + .55*glow);
  const th = th0 + e*turn;
  const hx = s, hy = s*asp, ihx = s*rr, ihy = s*rr*asp, ith = th + turn;
  const ringPx = s*(1-rr)*.7;
  const c = landing(ai, near, lit);

  // landing slab = outer rect with the NEXT floor's rotated rect knocked out
  if (!bp && !noir){
    noStroke(); fill(c[0], c[1], c[2], 100);
    beginShape();
    const o0=rot(-hx,-hy,th), o1=rot(hx,-hy,th), o2=rot(hx,hy,th), o3=rot(-hx,hy,th);
    vertex(o0[0],o0[1]); vertex(o1[0],o1[1]); vertex(o2[0],o2[1]); vertex(o3[0],o3[1]);
    beginContour();
    const i3=rot(-ihx,ihy,ith), i2=rot(ihx,ihy,ith), i1=rot(ihx,-ihy,ith), i0=rot(-ihx,-ihy,ith);
    vertex(i3[0],i3[1]); vertex(i2[0],i2[1]); vertex(i1[0],i1[1]); vertex(i0[0],i0[1]);
    endContour();
    endShape(CLOSE);
  }

  // engraved hatching across the landing
  if (paper && ringPx > 4 && s < B0*1.7){
    const dark = cl(1 - (c[2]-38)/57, 0, 1), nh = Math.round(1 + 5*dark);
    ink(30); noFill();
    for (let i=0;i<nh;i++){ const q=(i+1)/(nh+1);
      beginShape();
      for (let t=0;t<=16;t++){ const tt=t/16;
        const a2=per(hx,hy,th,tt), b2=per(ihx,ihy,ith,tt);
        vertex(a2[0]+(b2[0]-a2[0])*q, a2[1]+(b2[1]-a2[1])*q);
      }
      endShape();
    }
  }

  // two flights of treads spanning opposite quadrants of the ring
  if (ringPx > 3 && s < B0*3.4){
    const nt2 = Math.max(2, Math.round(ntd * cl(ringPx/(u*.055), .12, 1)));
    const filled = ringPx > 6 && !bp && !noir && !paper;
    for (let fs=0; fs<2; fs++){
      const t0 = fs*.5, t1 = t0 + .25;
      for (let i=0;i<nt2;i++){
        const ta = t0 + (t1-t0)*(i/nt2), tb = t0 + (t1-t0)*((i+1)/nt2);
        const oa = per(hx,hy,th,ta), ob = per(hx,hy,th,tb);
        const ia = per(ihx,ihy,ith,ta), ib = per(ihx,ihy,ith,tb);
        if (filled){
          const nose = (i & 1) ? 1.24 : .78;
          noStroke(); fill(c[0], cl(c[1]*.9,0,100), cl(c[2]*nose + ((i&1) ? 6*lit : -3), 2, 96), 100);
          quad(oa[0],oa[1], ob[0],ob[1], ib[0],ib[1], ia[0],ia[1]);
        } else {
          ink(bp?76:(noir? 24+62*lit : 38)); noFill();
          line(oa[0],oa[1], ia[0],ia[1]);
        }
      }
    }
  }

  // balustrade around the void — the bright metal edge (carries the noir style)
  if (s > u*.025 && s < B0*3.8){
    ink(cl(bp?86 : (noir ? 32 + 64*lit : 28 + 60*lit*glow), 0, 100));
    strokeWeight(Math.max(1, u*.0024*cl(near+.35,0,1.4)));
    noFill(); beginShape();
    for (let t=0;t<4;t++){ const p2 = per(ihx*1.055, ihy*1.055, ith, t/4); vertex(p2[0],p2[1]); }
    endShape(CLOSE);
    strokeWeight(SW);
  }

  // outer wall edge
  if (!noir && s < B0*3.4 && s > u*.02){
    ink(bp?60:(paper?42:20)); noFill(); beginShape();
    for (let t=0;t<4;t++){ const p2 = per(hx,hy,th,t/4); vertex(p2[0],p2[1]); }
    endShape(CLOSE);
  }
}

// ---- skylight bloom over the void ------------------------------------------
if (!bp && !paper){
  push(); blendMode(ADD); noStroke();
  const fl = .5 + .5*Math.sin(K.t*.147+.6);
  for (let i=4;i>=1;i--){
    fill(H, 24, 100, 2.0 + 3.2*glow*fl);
    ellipse(cx, cy, u*(.10+.085*i), u*(.10+.085*i)*asp);
  }
  pop(); blendMode(BLEND);
}
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
